document.getElementById('activeSchool').onchange=e=>{school.schoolId=e.target.value;school.classId='';school.studentId='';saveSchool();render()};
document.getElementById('activeClass').onchange=e=>{school.classId=e.target.value;saveSchool();render()};document.getElementById('activeStudent').onchange=e=>{school.studentId=e.target.value;saveSchool();render()};document.getElementById('activeTeacher').onchange=e=>{school.teacherId=e.target.value;saveSchool();render()};
document.getElementById('addClass').onclick=()=>{if(cloud.ready){cloudAdmin('class');return}if(!['admin','manager'].includes(role))return;const input=document.getElementById('newClassName'),name=input.value.trim();if(!name)return;const id=crypto.randomUUID();if(!activeSchoolId())return;school.classes.push({id,name,schoolId:activeSchoolId()});activeTeacher()?.classIds.push(id);school.classId=id;school.studentId='';saveSchool();input.value='';render()};
document.getElementById('addStudent').onclick=()=>{if(cloud.ready){cloudAdmin('student');return}if(!['admin','manager','teacher'].includes(role)||!activeClassId())return;const input=document.getElementById('newStudentName'),name=input.value.trim();if(!name)return;const id=crypto.randomUUID();school.students.push({id,name,classIds:[school.classId]});school.studentId=id;saveSchool();input.value='';render()};
document.getElementById('addTeacher').onclick=()=>{if(cloud.ready){cloudAdmin('teacher');return}if(!['admin','manager'].includes(role))return;const input=document.getElementById('newTeacherName'),name=input.value.trim();if(!name)return;school.teachers.push({id:crypto.randomUUID(),name,classIds:[school.classId]});saveSchool();input.value='';render()};

document.getElementById('addSchool').onclick=()=>{if(cloud.ready){cloudAdmin('school');return}if(role!=='admin')return;const input=document.getElementById('newSchoolName'),name=input.value.trim();if(!name)return;const id=crypto.randomUUID();school.schools.push({id,name,ownerId:school.teacherId});school.schoolId=id;school.classId='';school.studentId='';saveSchool();input.value='';render()};
